insert into public.practice_exercises (id, slug, title, summary, skill, band_group, question_types, duration_minutes, question_count, passage, audio_path, audio_mime, audio_bytes, is_published) values ('6bef1a8a-3efe-5a38-b7d6-40c0370f4def', 'the-community-garden', 'The community garden', 'Khám phá một khu vườn nhỏ và thay đổi lớn trong khu phố.', 'reading', 'below_5', array['multiple_choice', 'true_false_not_given', 'gap_fill']::text[], 10, 5, array['A. There used to be an empty piece of land behind East Street Library. People walked past it on their way to work, but nobody stopped there. In March, a group of neighbours asked the council if they could use the land to grow vegetables. The council agreed to lend it to them for three years. The neighbours did not have to pay rent, but they had to keep the area clean and open to everyone during the day.', 'B. The first job was to remove rubbish. Twenty volunteers came on a Saturday morning, including two people who had never grown a plant before. A local shop gave them tools, and the library put a notice in its window asking for seeds. By the end of April, there were rows of carrots and beans. The group collected rainwater in large containers because there was no tap in the garden.', 'C. Now the garden opens at nine each morning. Visitors can sit on wooden benches, and children have a small area where they grow flowers. The volunteers share the vegetables rather than sell them. They say the most important result is that neighbours have started talking to one another. They hope to build a small shelter next year so that people can still meet when it rains.']::text[], null, null, null, true);
