insert into public.practice_exercises (id, slug, title, summary, skill, band_group, question_types, duration_minutes, question_count, passage, audio_path, audio_mime, audio_bytes, is_published) values ('3dfb2311-e214-5248-9f64-46953f164ce8', 'libraries-without-walls', 'Libraries without walls', 'Thư viện hiện đại mở rộng vai trò như thế nào?', 'reading', '5_6', array['matching_headings', 'multiple_choice', 'true_false_not_given', 'gap_fill']::text[], 15, 5, array['A. When the library in Westford announced that it would lend sewing machines, the response was mixed. Some residents welcomed the idea; others wondered whether the institution was forgetting its purpose. For librarian Maya Collins, however, a library has always been about access. Books are one way of sharing knowledge, but they are not the only way. A resident who borrows a machine and learns to repair a jacket has gained a practical skill without buying expensive equipment.', 'B. Before expanding the service, staff carried out a survey. They expected requests for cameras and computer equipment. Those items were popular, but gardening tools attracted even more interest. The library therefore began with a small collection of tools and ran free demonstrations on Saturday afternoons. It did not purchase everything that people requested. Equipment that required specialist supervision was excluded, and every item had to fit into the existing storage room.', 'C. The project brought challenges. Returned items needed checking, and the original booking system could not manage objects that had several separate parts. Staff developed a checklist and allowed extra time between loans. Although maintaining the collection takes work, fewer items have been damaged than expected. A university team is now measuring whether borrowers buy less equipment themselves. Early interviews suggest that people value the chance to try something before deciding whether to own it.', 'D. The library still spends most of its budget on reading materials. Collins argues that the new collection supports that work rather than replacing it. Someone who attends a repair workshop may later borrow a book about design. The building has become a place where readers, makers and people looking for advice meet. Whether the model can succeed in smaller libraries will depend on available staff time, storage and local demand.']::text[], null, null, null, true);
