insert into public.practice_questions (id, exercise_id, position, type, instruction, prompt, options) values ('e408b130-80c3-5d2e-8d06-d4fd4b27793d', 'd8995187-5143-5a8b-88a1-099ebea8613d', 5, 'true_false_not_given', 'Choose TRUE, FALSE or NOT GIVEN.', 'Mereton''s programme was cheaper than installing reflective roofs.', '["TRUE", "FALSE", "NOT GIVEN"]'::jsonb);
insert into public.practice_questions (id, exercise_id, position, type, instruction, prompt, options) values ('a06e2581-c5eb-55f6-9e28-6c239b7a9b1e', 'd8995187-5143-5a8b-88a1-099ebea8613d', 6, 'multiple_choice', 'Choose ONE answer.', 'What is the writer''s overall recommendation?', '["Include trees within a wider heat strategy.", "Replace ventilation programmes with trees.", "Plant only where residents can pay.", "Avoid measuring long-term outcomes."]'::jsonb);
insert into public.practice_exercises (id, slug, title, summary, skill, band_group, question_types, duration_minutes, question_count, passage, audio_path, audio_mime, audio_bytes, is_published) values ('5b4737f7-c7ee-557f-b237-5f2ff7445f06', 'the-paradox-of-predictable-cities', 'The paradox of predictable cities', 'Phân tích lập luận về dữ liệu, mô hình và hành vi đô thị.', 'reading', '8_plus', array['matching_headings', 'true_false_not_given', 'multiple_choice', 'gap_fill']::text[], 22, 6, array['A. Urban models promise to turn the apparent disorder of city life into patterns that can inform decisions. Passenger movements, energy demand and deliveries all generate records from which recurring relationships can be inferred. The temptation is to regard a sufficiently detailed model as a transparent window onto the city itself. Yet a model is a selective description: its categories determine which activities become visible and which are treated as noise. Increasing the volume of observations does not remove that selection.', 'B. Consider a transport model calibrated against trips recorded by a mobile application. If people who travel infrequently or cannot afford reliable mobile data are underrepresented, the model may underestimate demand along the routes they use. The resulting timetable can then discourage those journeys further. What began as a measurement gap becomes an apparent confirmation of the original estimate. The difficulty is not simply that the sample is incomplete; the decisions informed by the sample can reshape the behaviour being measured.', 'C. This feedback does not make prediction useless. It changes what a responsible prediction must disclose. A forecast of passenger numbers under an unchanged timetable answers a different question from a forecast under improved service. Combining the two without stating the assumption gives an illusion of certainty. Some planning teams now publish several scenarios and explain which decisions could cause outcomes to diverge. Critics sometimes describe this as indecision, although an explicit range may be more informative than a single precise number whose conditions remain hidden.', 'D. A further complication concerns the difference between accuracy and usefulness. A model may reproduce the total number of journeys with impressive precision while distributing them incorrectly between neighbourhoods. For a budget overview, the aggregate may be adequate. For deciding where to add a bus stop, it is inadequate. Evaluation therefore needs to be tied to the decision at hand. There is no context-free score that guarantees a model will serve every planning purpose equally well.', 'E. Participatory approaches offer one response. Residents can identify missing routes, informal services and barriers that numerical records fail to capture. Their accounts do not automatically resolve disputes: participants may have conflicting interests, and the most vocal group may not represent everyone. Nevertheless, treating such accounts as evidence rather than decorative consultation can reveal assumptions before they become embedded in infrastructure. Quantitative and qualitative methods are complementary when each is allowed to challenge the other''s categories.', 'F. The paradox is that a useful model may make its own initial prediction obsolete. If a warning about overcrowding leads to additional services, the forecast crowding may never occur. Judging the warning solely by its failure to materialise would confuse a successful intervention with a defective forecast. Models should thus be assessed not only as descriptions of a fixed world but as participants in a changing one. Their value lies in supporting accountable decisions, including decisions that alter the patterns from which the models were built.']::text[], null, null, null, true);
