insert into public.practice_questions (id, exercise_id, position, type, instruction, prompt, options) values ('8d76b8b8-d70f-59df-863c-feef8a9d2386', '5b4737f7-c7ee-557f-b237-5f2ff7445f06', 6, 'multiple_choice', 'Choose ONE answer.', 'Why might an effective model make its prediction obsolete?', '["Its warning can prompt an intervention that changes the outcome.", "Every additional record weakens a forecast.", "Public consultation removes the need for services.", "The model''s categories become automatically neutral."]'::jsonb);
